def rpn_eval(tokens):
    """Evaluate a list of RPN tokens and return a float."""
    if not tokens:
        raise ValueError('empty expression')
    stack = []
    _OPS = {"+", "-", "*", "/"}
    for tok in tokens:
        if tok in _OPS:
            if len(stack) < 2:
                raise ValueError('insufficient operands')
            b = stack.pop()
            a = stack.pop()
            if tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            elif tok == "*":
                stack.append(a * b)
            else:
                stack.append(a / b)
        else:
            try:
                stack.append(float(tok))
            except ValueError:
                raise ValueError(f'unknown token: {tok}')
    if len(stack) != 1:
        raise ValueError('expression leaves more than one value')
    return stack[0]

