def normalize_path(path: str) -> str:
    """Normalize a POSIX-style path string."""
    if not path:
        return "."
    absolute = path.startswith("/")
    parts = path.split("/")
    out = []
    for p in parts:
        if p == "" or p == ".":
            continue
        if p == "..":
            if out:
                out.pop()
        else:
            out.append(p)
    result = "/".join(out)
    if absolute:
        result = "/" + result
    if not result and not absolute:
        return "."
    if result == "" and absolute:
        return "/"
    return result

