def parse_csv_line(line: str) -> list[str]:
    """Parse one CSV line into a list of fields."""
    fields = []
    current_field = ""
    in_quotes = False
    prev_char = None
    for char in line:
        if char == '"' and not in_quotes:
            in_quotes = True
        elif char == '"' and in_quotes and prev_char == '"":
            current_field += '"'
        elif char == '"' and in_quotes and prev_char != '"":
            in_quotes = False
        elif char == ',' and not in_quotes:
            fields.append(current_field)
            current_field = ""
        else:
            current_field += char
        prev_char = char
    fields.append(current_field)
    return fields

